@import url("https://fonts.googleapis.com/css2?family=Wix+Madefor+Display:wght@600;700;800&family=Wix+Madefor+Text:wght@400;500;600&display=swap");
:root{--pu:#4B2E83;--pu2:#3A2266;--sf:#FFC93C;--li:#F2EEF9;--ink:#1E1A2B;--gr:#5B5670;--ln:#E3DDF0;--h:"Wix Madefor Display",system-ui,sans-serif;--b:"Wix Madefor Text",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:800;margin:0;line-height:1.08;letter-spacing:-.01em}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--sf);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--sf);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:80px;position:relative}.logo{font-family:var(--h);font-weight:800;font-size:24px;text-decoration:none;color:var(--pu);display:flex;gap:10px;align-items:center}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:500;align-items:center}.menu a{text-decoration:none}.menu .cta{background:var(--sf);padding:10px 18px;border-radius:12px;font-weight:600}
.burger{display:none;background:none;border:2px solid var(--pu);color:var(--pu);width:44px;height:40px;border-radius:10px;font-size:20px;cursor:pointer}
.hero{padding:40px 0 90px;position:relative;overflow:hidden}.hero .wrap{display:grid;grid-template-columns:1.05fr .95fr;gap:50px;align-items:center}
.hero h1{font-size:clamp(44px,5.8vw,78px);color:var(--pu)}.hero h1 mark{background:linear-gradient(transparent 60%,var(--sf) 60%);color:inherit;padding:0 4px}
.hero p{font-size:19px;color:var(--gr);margin:22px 0 28px;max-width:30em}
.btn{display:inline-block;background:var(--pu);color:#fff;text-decoration:none;font:600 17px var(--b);padding:15px 26px;border-radius:14px;border:0;cursor:pointer}.btn.y{background:var(--sf);color:var(--ink)}
.row{display:flex;flex-wrap:wrap;gap:12px}
.stack{position:relative;height:530px}
.tc{position:absolute;background:#fff;border-radius:22px;box-shadow:0 20px 50px rgba(75,46,131,.18);padding:16px;display:flex;gap:14px;align-items:center;width:320px}
.tc img{width:64px;height:64px;border-radius:16px;object-fit:cover}.tc b{display:block;font-family:var(--h);font-size:19px}.tc span{font-size:14px;color:var(--gr)}
.tc.a{top:10px;left:0;transform:rotate(-3deg)}.tc.b{top:150px;right:0;transform:rotate(2deg)}.tc.c{top:300px;left:30px;transform:rotate(-1deg)}
.blob{position:absolute;inset:40px 30px;background:var(--li);border-radius:40% 60% 55% 45%/50% 40% 60% 50%}
.stat{position:absolute;right:20px;bottom:10px;background:var(--pu);color:#fff;border-radius:18px;padding:14px 18px;font-size:14px}.stat b{display:block;font-family:var(--h);font-size:30px;color:var(--sf)}
section{padding:86px 0}.sh{max-width:640px;margin-bottom:30px}.sh h2{font-size:clamp(34px,4.4vw,54px);color:var(--pu)}.sh p{color:var(--gr);margin:12px 0 0;font-size:18px}
.tut{background:var(--li)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:26px}.chips button{font:600 15px var(--b);background:#fff;border:2px solid transparent;border-radius:12px;padding:9px 16px;cursor:pointer;color:var(--ink)}.chips button[aria-pressed=true]{background:var(--pu);color:#fff}
.tg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.tu{background:#fff;border-radius:22px;padding:22px;display:flex;flex-direction:column}
.tu .top{display:flex;gap:14px;align-items:center;margin-bottom:12px}.tu img{width:72px;height:72px;border-radius:18px;object-fit:cover}.tu h3{font-size:22px}.tu .r{font-size:14px;color:var(--gr)}.tu .r b{color:#B7791F}
.tu p{margin:0 0 12px;color:var(--gr);font-size:16px;flex:1}.tu .sb{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}.tu .sb span{font-size:13px;background:var(--li);border-radius:8px;padding:3px 9px;font-weight:500}
.tu .ft{display:flex;justify-content:space-between;align-items:center;gap:10px}.tu .pr{font-family:var(--h);font-weight:800;font-size:20px}.tu .pr small{font:400 14px var(--b);color:var(--gr)}
.tu button{font:600 15px var(--b);background:var(--sf);border:0;border-radius:10px;padding:9px 14px;cursor:pointer}
.calc .cg{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:start}.calc .cg>div{min-width:0}
.cf{border:2px solid var(--ln);border-radius:22px;padding:28px}.cf fieldset{border:0;padding:0;margin:0 0 22px}.cf legend,.cf .lb{font-weight:600;margin-bottom:10px;display:block}
.opt{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.opt2{grid-template-columns:1fr 1fr}.opt label{cursor:pointer;position:relative}.opt input{position:absolute;opacity:0;left:0;top:0;width:1px;height:1px}
.opt span{display:block;border:2px solid var(--ln);border-radius:12px;padding:12px;text-align:center;font-weight:600;font-size:15px;height:100%}.opt span small{display:block;font-weight:400;color:var(--gr);font-size:13px}
.opt input:checked+span{border-color:var(--pu);background:var(--li)}.opt input:focus-visible+span{outline:3px solid var(--sf);outline-offset:2px}
.rg{display:flex;align-items:center;gap:14px}.rg input{flex:1;accent-color:var(--pu)}.rg output{font-family:var(--h);font-weight:800;font-size:24px;min-width:90px;text-align:right}
.res{background:var(--pu);color:#fff;border-radius:22px;padding:28px;position:sticky;top:20px}.res h3{font-size:22px;color:var(--sf)}
.res .big{font-family:var(--h);font-weight:800;font-size:60px;line-height:1;margin:14px 0 4px}.res .big small{font:400 17px var(--b)}
.res ul{list-style:none;padding:0;margin:18px 0 22px}.res li{display:flex;justify-content:space-between;padding:8px 0;border-top:1px solid rgba(255,255,255,.18);font-size:15px}
.how ol{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;counter-reset:s}.how li{counter-increment:s;background:var(--li);border-radius:22px;padding:26px}
.how li:before{content:counter(s);display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:var(--sf);font-family:var(--h);font-weight:800;font-size:22px;margin-bottom:14px}.how h3{font-size:22px}.how p{margin:6px 0 0;color:var(--gr)}
.trial{background:var(--pu);color:#fff}.trial .wrap{display:grid;grid-template-columns:.9fr 1.1fr;gap:50px}.trial .sh h2{color:#fff}.trial .sh p{color:#D4C8EC}
.trial form{background:#fff;color:var(--ink);border-radius:22px;padding:30px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
.trial label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}.trial input,.trial select,.trial textarea{width:100%;font:16px var(--b);padding:12px;border:2px solid var(--ln);border-radius:12px;margin-bottom:14px;color:var(--ink);background:#fff}
.msg{visibility:hidden;margin:12px 0 0;font-weight:600;color:var(--pu)}.msg.on{visibility:visible}
footer{padding:30px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero .wrap,.calc .cg,.trial .wrap{grid-template-columns:1fr}.tg{grid-template-columns:1fr 1fr}.res{position:static}.how ol{grid-template-columns:1fr}.stack{height:420px;max-width:440px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:80px;left:0;right:0;background:#fff;flex-direction:column;align-items:flex-start;padding:18px 22px;z-index:30;box-shadow:0 10px 20px rgba(0,0,0,.06)}.menu.open{display:flex}.tg{grid-template-columns:1fr}.opt{grid-template-columns:1fr 1fr}.fr{grid-template-columns:1fr}.tc{width:280px}.tc.b{right:auto;left:24px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=200&h=200&q=75&auto=format&fit=crop`;
const T=[["Emma","1438761681033-6461ffad8d80",["Maths"],"Makes algebra feel like a puzzle, not a punishment. Former secondary maths teacher.",4.9,38],["Daniel","1507003211169-0a1dd7228f2d",["Science","Maths"],"Medical student who loves explaining how the body works with everyday examples.",4.8,38],["Sofia","1544005313-94ddf0286df2",["English","11+"],"Helps nervous readers love books and gets 11+ students ready for exam day.",5.0,35],["James","1500648767791-00dcc994a43e",["Maths","11+"],"Patient and calm. Great with students who've decided they're 'bad at maths'.",4.9,32],["Leila","1534528741775-53994a69daeb",["Languages","English"],"French and Spanish tutor, grew up speaking three languages at home.",4.8,40],["Tom","1535713875002-d1d0cf377fde",["Science"],"Physics and chemistry for GCSE and A-level. Explains things with drawings.",4.7,42]];
let sub='all';function tutors(){$('tg').innerHTML=T.filter(t=>sub==='all'||t[2].includes(sub)).map(t=>`<article class="tu"><div class="top"><img src="${U(t[1])}" alt="${t[0]}, tutor" width="72" height="72" loading="lazy"><div><h3>${t[0]}</h3><span class="r"><b>★ ${t[4].toFixed(1)}</b> from parent reviews</span></div></div><div class="sb">${t[2].map(s=>`<span>${s}</span>`).join('')}</div><p>${t[3]}</p><div class="ft"><span class="pr">from £${t[5]}<small> an hour</small></span><button type="button" data-t="${t[0]}">Try ${t[0]} free</button></div></article>`).join('')}
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));sub=b.dataset.s;tutors()};tutors();
$('tt').innerHTML='<option>Any tutor, you choose</option>'+T.map(t=>`<option>${t[0]}</option>`).join('');
$('tg').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('tt').value=b.dataset.t;$('trial').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
const g=n=>'£'+Math.round(n).toLocaleString('en-GB');
function calc(){const l=document.querySelector('input[name=lv]:checked'),f=document.querySelector('input[name=fm]:checked'),h=+$('hw').value,w=+$('wk').value;const ph=l.value*f.value,pw=ph*h;
$('hwo').textContent=h+(h===1?' hour':' hours');$('wko').textContent=w+' weeks';$('rt').textContent=`${l.dataset.n}, ${f.dataset.n.toLowerCase()}`;
$('rm').innerHTML=`${g(pw*52/12)}<small> a month</small>`;$('rh').textContent=g(ph);$('rw').textContent=g(pw);$('rc').textContent=g(pw*w)}
$('cf').addEventListener('input',calc);calc();
$('tf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Thanks ${$('tn').value}. We'll call you within one working day to book your free lesson${$('tt').value.startsWith('Any')?'':' with '+$('tt').value}.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
